#include <stdio.h>
#include <string.h>

#define INF 1000000000
#define MAXN 105

int dist[MAXN][MAXN];
int n, m;

int main() {
    int i, j, k;

    scanf("%d %d", &n, &m);

    // Initialize distance matrix
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            if (i == j) dist[i][j] = 0;
            else dist[i][j] = INF;
        }
    }

    // Read edges
    for (i = 0; i < m; i++) {
        int u, v, w;
        scanf("%d %d %d", &u, &v, &w);
        u--; v--;
        if (dist[u][v] > w) {
            dist[u][v] = w;
        }
    }

    // Floyd-Warshall
    for (k = 0; k < n; k++) {
        for (i = 0; i < n; i++) {
            for (j = 0; j < n; j++) {
                if (dist[i][k] != INF && dist[k][j] != INF) {
                    if (dist[i][j] > dist[i][k] + dist[k][j]) {
                        dist[i][j] = dist[i][k] + dist[k][j];
                    }
                }
            }
        }
    }

    // Check for negative cycles
    for (i = 0; i < n; i++) {
        if (dist[i][i] < 0) {
            printf("NEGATIVE CYCLE\n");
            return 0;
        }
    }

    // Output result
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            if (j > 0) printf(" ");
            if (dist[i][j] == INF) printf("INF");
            else printf("%d", dist[i][j]);
        }
        printf("\n");
    }

    return 0;
}

