#define INF 4000000000000000000LL

int main(void) {
    int V, E;
    if (scanf("%d %d", &V, &E) != 2) return 0;

    long long *dist = (long long *)malloc((size_t)V * V * sizeof(long long));
    if (!dist) return 0;

    for (int i = 0; i < V; i++) {
        for (int j = 0; j < V; j++) {
            dist[i * V + j] = (i == j) ? 0 : INF;
        }
    }

    for (int i = 0; i < E; i++) {
        int s, t;
        long long d;
        scanf("%d %d %lld", &s, &t, &d);
        if (d < dist[s * V + t]) dist[s * V + t] = d;
    }

    for (int k = 0; k < V; k++) {
        for (int i = 0; i < V; i++) {
            long long dik = dist[i * V + k];
            if (dik == INF) continue;
            for (int j = 0; j < V; j++) {
                long long dkj = dist[k * V + j];
                if (dkj == INF) continue;
                long long nd = dik + dkj;
                if (nd < dist[i * V + j]) {
                    dist[i * V + j] = nd;
                }
            }
        }
    }

    for (int i = 0; i < V; i++) {
        if (dist[i * V + i] < 0) {
            printf("NEGATIVE CYCLE\n");
            free(dist);
            return 0;
        }
    }

    for (int i = 0; i < V; i++) {
        for (int j = 0; j < V; j++) {
            if (j) printf(" ");
            if (dist[i * V + j] == INF) printf("INF");
            else printf("%lld", dist[i * V + j]);
        }
        printf("\n");
    }

    free(dist);
    return 0;
}

